// Service worker: precache every app file, serve cache-first, so the app works
// with no internet after the first launch. User data is NOT here; it lives in
// IndexedDB / localStorage.
// APP_ID and VERSION must match js/config.js (a unit test checks). Bump VERSION
// for every release, or devices keep the old files.
const APP_ID = 'my-offline-app';
const VERSION = '0.1.0';
const CACHE = `${APP_ID}-${VERSION}`;

// Generated by `npm run precache`; a unit test fails if an app file is missing.
const PRECACHE = [
  './',
  'assets/app/app-icon-maskable.svg',
  'assets/app/app-icon.svg',
  'css/app.css',
  'css/tokens.css',
  'icons/apple-touch-icon.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-512.png',
  'index.html',
  'js/app.js',
  'js/backup.js',
  'js/config.js',
  'js/icons.js',
  'js/pwa.js',
  'js/screens/home.js',
  'js/screens/settings-screen.js',
  'js/settings.js',
  'js/store.js',
  'js/ui.js',
  'js/zip.js',
  'manifest.webmanifest',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE.map((p) => new Request(p, { cache: 'reload' }))))
  );
  // No skipWaiting here: the page shows "A new version is ready" and the
  // person decides when to refresh, so nothing reloads in the middle of a task.
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(`${APP_ID}-`) && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // Navigations (any route) get the app shell.
    if (req.mode === 'navigate') {
      const shell = (await cache.match('index.html')) || (await cache.match('./'));
      if (shell) return shell;
    }
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (e) {
      if (req.mode === 'navigate') {
        const shell = await cache.match('index.html');
        if (shell) return shell;
      }
      throw e;
    }
  })());
});
